import{_ as t,o as e,c as r,a as o}from"./chunks/framework.Bw0S3kgV.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"md/07-文件及文件夹批处理/709-监测指定文件夹修改文件名为所在文件夹名称并移动到指定文件夹下.md","filePath":"md/07-文件及文件夹批处理/709-监测指定文件夹修改文件名为所在文件夹名称并移动到指定文件夹下.md"}'),n={name:"md/07-文件及文件夹批处理/709-监测指定文件夹修改文件名为所在文件夹名称并移动到指定文件夹下.md"};function p(i,a,l,s,h,_){return e(),r("div",null,[...a[0]||(a[0]=[o('<h2 id="_709-监测指定文件夹修改文件名为所在文件夹名称并移动到指定文件夹下" tabindex="-1">709-监测指定文件夹修改文件名为所在文件夹名称并移动到指定文件夹下 <a class="header-anchor" href="#_709-监测指定文件夹修改文件名为所在文件夹名称并移动到指定文件夹下" aria-label="Permalink to &quot;709-监测指定文件夹修改文件名为所在文件夹名称并移动到指定文件夹下&quot;">​</a></h2><p>监测指定文件夹，以文件所在文件夹名命名文件名称，监测到文件后移动到指定文件夹，</p><p>如果一个文件夹下有多个文件，则自动添加 _1 这样的数字序列，不同格式文件接续序列。</p><p>【1】、支持的文件格式：所有文件格式</p><p>【2】、是否支持子文件夹穿透：支持</p><p>【说明】如果需要多开则再次打开一个程序即可，可实现监测多个文件夹，需要目标文件夹路径不同，</p><p>如果目标文件夹相同的情况下，源文件夹下文件夹名称相同则会出现覆盖的情况，特别注意！</p><h3 id="📑-使用场景例子展示" tabindex="-1">📑 使用场景例子展示 <a class="header-anchor" href="#📑-使用场景例子展示" aria-label="Permalink to &quot;📑 使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多支持的文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有支持的文件。</p><p>只需要输入A文件夹和处理后输出的文件夹路径即可。</p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统<br> 注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://s2.loli.net/2024/11/07/TmsbWNFAqp2nMwa.png" alt="image-20241107105457824.png"></p><h3 id="📑-视频演示" tabindex="-1">📑 视频演示 <a class="header-anchor" href="#📑-视频演示" aria-label="Permalink to &quot;📑 视频演示&quot;">​</a></h3><p><a href="https://www.bilibili.com/video/BV1ADD1YPEcP/" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1ADD1YPEcP/</a></p><h3 id="📑-win-mac程序定制说明" tabindex="-1">📑 win/mac程序定制说明 <a class="header-anchor" href="#📑-win-mac程序定制说明" aria-label="Permalink to &quot;📑 win/mac程序定制说明&quot;">​</a></h3><blockquote><p>程序定制微信：reset201901</p><p>1、明确自身需求，直入主题，简要描述；</p><p>2、我第一步想要怎样，第二步想要怎样...；</p><p>3、最终想要的结果是什么样的，自己能够清晰的描述出来,</p><p>4、最好是用txt文档将以上需求写清楚，或者录制视频将需求讲述清楚；</p><p>5、提供需要做测试的文件给我们，如果文件不便展示，可以创建一个txt文件将文件名后缀.txt修改为你同类型的文件即可。</p></blockquote><h3 id="📑-本工具下载地址" tabindex="-1">📑 本工具下载地址 <a class="header-anchor" href="#📑-本工具下载地址" aria-label="Permalink to &quot;📑 本工具下载地址&quot;">​</a></h3><p><strong>下载地址：</strong></p><p><a href="http://www.softbangong.top/?id=43" target="_blank" rel="noreferrer">http://www.softbangong.top/?id=43</a></p><hr><h3 id="📑-友情提示" tabindex="-1">📑 友情提示 <a class="header-anchor" href="#📑-友情提示" aria-label="Permalink to &quot;📑 友情提示&quot;">​</a></h3><p><strong>正式使用前请先测试/备份原文件，然后再大批量使用，以免造成不可逆损失。</strong></p><hr><h3 id="📑-关注微信公众号不迷路" tabindex="-1">📑 关注微信公众号不迷路 <a class="header-anchor" href="#📑-关注微信公众号不迷路" aria-label="Permalink to &quot;📑 关注微信公众号不迷路&quot;">​</a></h3><p><img src="https://s2.loli.net/2024/11/02/tK9T7jxLcuv5rUk.png" alt="image"></p><blockquote><p>作者：极致办公 / 微信：reset201901</p><p>本文网址：<a href="https://doc.softbangong.top/#/md/07-%E6%96%87%E4%BB%B6%E5%8F%8A%E6%96%87%E4%BB%B6%E5%A4%B9%E6%89%B9%E5%A4%84%E7%90%86/709-%E7%9B%91%E6%B5%8B%E6%8C%87%E5%AE%9A%E6%96%87%E4%BB%B6%E5%A4%B9%E4%BF%AE%E6%94%B9%E6%96%87%E4%BB%B6%E5%90%8D%E4%B8%BA%E6%89%80%E5%9C%A8%E6%96%87%E4%BB%B6%E5%A4%B9%E5%90%8D%E7%A7%B0%E5%B9%B6%E7%A7%BB%E5%8A%A8%E5%88%B0%E6%8C%87%E5%AE%9A%E6%96%87%E4%BB%B6%E5%A4%B9%E4%B8%8B.md" target="_blank" rel="noreferrer">https://doc.softbangong.top/#/md/07-文件及文件夹批处理/709-监测指定文件夹修改文件名为所在文件夹名称并移动到指定文件夹下.md</a></p></blockquote>',28)])])}const E=t(n,[["render",p]]);export{d as __pageData,E as default};
